input.command:
cd /tmp/probe && cat > /tmp/probe/rule.awk <<'AWK'
BEGIN{FS="\t"; OFS="\t"}
{
  w=$1; obs=$2; lw=tolower(w); n=length(lw);
  last=substr(lw,n,1); last2=substr(lw,n-1,2);
  if (last=="y" && n>=2) {
    c=substr(lw,n-1,1);
    if (c!~/[aeiou]/) { pred=substr(lw,1,n-1) "ies" } else { pred=lw "s" }
  } else if (last2=="es") { pred=lw }
  else if (last=="s" || last2=="ch" || last2=="sh") { pred=lw "es" }
  else { pred=lw "s" }
  if (pred!=obs) print w, obs, pred
}
AWK
awk -f /tmp/probe/rule.awk data/common-nouns-m.tsv | sort > /tmp/probe/findings/cnm-dev.txt; wc -l /tmp/probe/findings/cnm-dev.txt; cat /tmp/probe/findings/cnm-dev.txt
